import{_ as t,o as a,c as r,a3 as i}from"./chunks/framework.z_KJ15Ep.js";const l="/bilder/unterricht-kataloge/kataloge-ortsteile.png",m=JSON.parse('{"title":"Ortsteile im Katalog verwalten","description":"","frontmatter":{"title":"Ortsteile im Katalog verwalten","source_pageid":345,"source_revision":1901},"headers":[],"relativePath":"schild3/unterricht-kataloge/ortsteile-allgemeine-kataloge.md","filePath":"schild3/unterricht-kataloge/ortsteile-allgemeine-kataloge.md"}'),n={name:"schild3/unterricht-kataloge/ortsteile-allgemeine-kataloge.md"};function s(o,e,g,c,d,h){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="ortsteile-im-katalog-verwalten" tabindex="-1">Ortsteile im Katalog verwalten <a class="header-anchor" href="#ortsteile-im-katalog-verwalten" aria-label="Permalink to &quot;Ortsteile im Katalog verwalten&quot;">​</a></h1><p>Ergänzen Sie Ortsteile, um Anschriften genauer zu erfassen und Schülergruppen bei Bedarf nach diesen Angaben auszuwählen.</p><p><a href="/bilder/unterricht-kataloge/kataloge-ortsteile.png"><img src="'+l+'" alt="Karteireiter Kataloge/Ortsteile" loading="lazy"></a></p><p><em>Karteireiter Kataloge/Ortsteile</em></p><p>Gerade für ländlichere Gemeinden bietet die Möglichkeit, Ortsteile angeben zu können, eine große Erleichterung. Oftmals sind unter einer Postleitzahl verschiedene Ortsteile einer Kommune zusammengefasst.</p><p>Durch Eingabe der Ortsteile kann nun auch gezielt danach gefiltert werden, was für Anfragen des Schulträgers häufig sinnvoll ist.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Ortsteile_(Allgemeine_Kataloge)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 1901.</p>',8)])])}const p=t(n,[["render",s]]);export{m as __pageData,p as default};
